 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = {7, 8}
    row_lines = [r for r in range(h) if any(v in marks for v in grid[r])]
    col_lines = [c for c in range(w) if any(grid[r][c] in marks for r in range(h))]

    # Marker positions sit at junctions; extend a regularly spaced lattice
    # leftward where the first junction has no special marker.
    if len(col_lines) >= 2:
        gaps = [b - a for a, b in zip(col_lines, col_lines[1:])]
        step = Counter(gaps).most_common(1)[0][0]
        while col_lines[0] - step >= 0:
            col_lines.insert(0, col_lines[0] - step)

    background = Counter(v for row in grid for v in row if v not in marks).most_common(1)[0][0]
    out = []
    for r0, r1 in zip(row_lines, row_lines[1:]):
        outrow = []
        for c0, c1 in zip(col_lines, col_lines[1:]):
            corners = [grid[r][c] for r in (r0, r1) for c in (c0, c1)]
            if corners[0] in marks and all(v == corners[0] for v in corners):
                outrow.append(corners[0])
            else:
                outrow.append(background)
        out.append(outrow)
    return out


if __name__ == "__main__":
